let book = {
    title: "JavaScript: The Good Parts",
    author: "Douglas Crockford",
    year: 2008
};

book.isAvailable = true; // Добавление
book.year = 2010;        // Изменение
delete book.pages;       // Удаление

let wordCounts = {};
let words = "hello world hello javascript world hello".split(" ");

for (let word of words) {
    wordCounts[word] = (wordCounts[word] || 0) + 1;
}

console.log(wordCounts); // { hello: 3, world: 2, javascript: 1 }

let scores = { math: 90, physics: 85, chemistry: 95 };

console.log(Object.keys(scores));   // ["math", "physics", "chemistry"]
console.log(Object.values(scores)); // [90, 85, 95]
console.log(Object.entries(scores)); // [["math", 90], ["physics", 85], ["chemistry", 95]]

for (let [subject, score] of Object.entries(scores)) {
    console.log(`${subject}: ${score}`);
}
